import java.io.*;
import java.net.*;
import org.json.*;
String rd(InputStream in) {
  BufferedReader r = new BufferedReader(new InputStreamReader(in, "UTF-8"));
  StringBuilder sb = new StringBuilder();
  String line;
  while ((line = r.readLine()) != null) sb.append(line).append("\n");
  r.close();
  return sb.toString();
}
int patchObj(Object o, String cls, JSONObject set) {
  int n = 0;
  if (o instanceof JSONObject) {
    JSONObject j = (JSONObject) o;
    if (cls.equals(j.optString("m_classType"))) {
      java.util.Iterator ki = set.keys();
      while (ki.hasNext()) { String k = (String) ki.next(); j.put(k, set.get(k)); }
      n++;
    }
    java.util.Iterator it2 = j.keys();
    java.util.ArrayList ks = new java.util.ArrayList();
    while (it2.hasNext()) ks.add(it2.next());
    for (int i = 0; i < ks.size(); i++) n += patchObj(j.opt((String) ks.get(i)), cls, set);
  } else if (o instanceof JSONArray) {
    JSONArray a = (JSONArray) o;
    for (int i = 0; i < a.length(); i++) n += patchObj(a.opt(i), cls, set);
  }
  return n;
}
try {
  HttpURLConnection c = (HttpURLConnection) new URL("https://samiullah-878.github.io/Noor-traders-/md/pkg.json?t=" + System.currentTimeMillis()).openConnection();
  c.setConnectTimeout(15000);
  c.setReadTimeout(30000);
  c.setUseCaches(false);
  JSONObject pk = new JSONObject(rd(c.getInputStream()));
  File newest = null;
  long now = System.currentTimeMillis();
  String[] ds = new String[] { "/storage/emulated/0/MacroDroid/Claude", "/storage/emulated/0/MacroDroid", "/storage/emulated/0" };
  for (int d = 0; d < ds.length; d++) {
    File[] fs = new File(ds[d]).listFiles();
    if (fs == null) continue;
    for (int i = 0; i < fs.length; i++) {
      File f = fs[i];
      String n = f.getName();
      if (f.isFile() && n.endsWith(".mdr") && !n.equals("claude.mdr") && now - f.lastModified() < 300000 && (newest == null || f.lastModified() > newest.lastModified())) newest = f;
    }
  }
  if (newest == null) return "err|Backup file nahi mili - MacroDroid ko All files access do";
  JSONObject ex = new JSONObject(rd(new FileInputStream(newest)));
  String mk = null;
  String vk = null;
  java.util.Iterator it = ex.keys();
  while (it.hasNext()) {
    String k = (String) it.next();
    JSONArray a = ex.optJSONArray(k);
    if (a == null || a.length() == 0) continue;
    JSONObject o = a.optJSONObject(0);
    if (o == null) continue;
    if (o.has("m_triggerList") && !o.optBoolean("isActionBlock", false) && mk == null) mk = k;
    if (o.has("m_name") && o.has("m_type") && !o.has("m_triggerList") && vk == null) vk = k;
  }
  if (mk == null) mk = ex.has("macroList") ? "macroList" : "macroList";
  if (vk == null) vk = ex.has("globalVariables") ? "globalVariables" : "variables";
  JSONArray macs = pk.getJSONArray("macros");
  JSONArray pts = pk.optJSONArray("patch");
  JSONArray cur0 = ex.optJSONArray(mk);
  if (pts != null && cur0 != null) for (int q = 0; q < pts.length(); q++) {
    JSONObject pt0 = pts.getJSONObject(q);
    for (int i = 0; i < cur0.length(); i++) {
      JSONObject m0 = cur0.getJSONObject(i);
      if (m0.optString("m_name").indexOf(pt0.optString("nm")) < 0) continue;
      int hit = patchObj(m0, pt0.optString("cls"), pt0.getJSONObject("set"));
      if (hit > 0) macs.put(m0);
    }
  }
  ex.put(mk, macs);
  JSONArray cur = ex.optJSONArray(vk);
  java.util.HashSet have = new java.util.HashSet();
  if (cur != null) for (int i = 0; i < cur.length(); i++) have.add(cur.getJSONObject(i).optString("m_name"));
  JSONArray add = new JSONArray();
  JSONArray pv = pk.optJSONArray("vars");
  if (pv != null) for (int i = 0; i < pv.length(); i++) if (!have.contains(pv.getJSONObject(i).optString("m_name"))) add.put(pv.getJSONObject(i));
  ex.put(vk, add);
  FileOutputStream o2 = new FileOutputStream("/storage/emulated/0/MacroDroid/Claude/claude.mdr");
  o2.write(ex.toString().getBytes("UTF-8"));
  o2.close();
  JSONArray off = pk.optJSONArray("off");
  for (int i = 1; i <= 5; i++) {
    String nm = (off != null && off.length() >= i) ? off.getString(i - 1) : "";
    try { variableSetter.setString("crOff" + i, nm, 1); } catch (Exception e2) { }
  }
  FileOutputStream o3 = new FileOutputStream("/storage/emulated/0/MacroDroid/Claude/have4.txt");
  o3.write(pk.optString("v").getBytes("UTF-8"));
  o3.close();
  return "ok|" + pk.optString("note");
} catch (Exception e) {
  return "err|" + e;
}
